<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { api, apiError, type ExperimentAssignment } from '../api/client'
import { useRouter } from 'vue-router'
const router=useRouter();const assignments=ref<ExperimentAssignment[]>([]);const loading=ref(true);const error=ref('');const working=ref(false)
async function load(){try{assignments.value=(await api.get<ExperimentAssignment[]>('/experiment-tasks')).data}catch(cause){error.value=apiError(cause,'实验任务暂时无法加载。')}finally{loading.value=false}}
async function start(assignment:ExperimentAssignment){working.value=true;error.value='';try{const current=(await api.post<ExperimentAssignment>('/experiment-tasks/'+assignment.id+'/start')).data;await router.push({path:'/experiments',query:{taskId:String(current.taskId),assignmentId:String(current.id)}})}catch(cause){error.value=apiError(cause,'实验任务启动失败。')}finally{working.value=false}}
onMounted(load)
</script>
<template><div class="page-stack experiment-tasks-page"><header class="page-heading"><div><p class="eyebrow">SERVER-MANAGED EXPERIMENTS</p><h1>实验任务</h1><p>任务、分组和完成状态由服务器记录；只有实际问答运行成功后才会完成任务。</p></div></header><div v-if="error" class="inline-notice" role="alert">{{ error }}</div><section v-if="loading" class="empty-state">正在加载实验任务…</section><section v-else class="task-list"><article v-for="task in assignments" :key="task.id" class="task-card"><div class="task-card-heading"><div><strong>{{ task.title }}</strong><small>{{ task.groupName }} · {{ task.conditionKey }} · {{ task.experimentType }}</small></div><span :class="['status-tag',task.status.toLowerCase()]">{{ task.status === 'ASSIGNED' ? '待开始' : task.status === 'IN_PROGRESS' ? '进行中' : '已完成' }}</span></div><p>{{ task.description || '完成指定问答实验并提交真实服务器结果。' }}</p><div class="task-question">{{ task.question }}</div><button class="primary-button" :aria-label="'开始实验任务 ' + task.id" :disabled="working || task.status === 'COMPLETED' || task.taskStatus !== 'OPEN'" @click="start(task)">{{ task.status === 'COMPLETED' ? '已完成' : task.taskStatus !== 'OPEN' ? '等待开放' : '开始实验' }}</button></article><div v-if="!assignments.length" class="empty-state">当前账户还没有被分配实验任务。</div></section></div></template>
<style scoped>.task-list{display:grid;gap:14px}.task-card{display:grid;gap:12px;padding:18px;background:#fff;border:1px solid var(--line);border-radius:10px;box-shadow:0 8px 24px rgba(31,66,48,.045)}.task-card-heading{display:flex;justify-content:space-between;gap:12px}.task-card-heading strong,.task-card-heading small{display:block}.task-card-heading small{margin-top:5px;color:var(--muted);font-size:10px}.task-card p{margin:0;color:#68766d;font-size:12px;line-height:1.6}.task-question{padding:10px 12px;color:#41564a;background:#f5f8f4;border-left:3px solid #5f9b78;font-size:12px}.status-tag{padding:4px 7px;border-radius:5px;font-size:10px}.status-tag.assigned{background:#fff3df;color:#9b681d}.status-tag.in_progress{background:#e7f0ff;color:#3f6494}.status-tag.completed{background:#e4f4e8;color:#2b7548}.primary-button{justify-self:start;min-height:34px;border:0;border-radius:6px;padding:0 14px;background:var(--accent);color:#fff;cursor:pointer}.primary-button:disabled{opacity:.5;cursor:not-allowed}</style>
